import React, { useContext, useEffect, useRef, useState } from "react";
import noteContext from "../context/notes/noteContext";
import { useNavigate } from "react-router-dom";

import Noteitem from "./Noteitem";
import AddNote from "./AddNote";
import SearchAndFilter from "./SearchAndFilter";
import NoteStats from "./NoteStats";
import UndoRedoButtons from "./UndoRedoButtons";

const Notes = (props) => {
  const context = useContext(noteContext);
  let navigate = useNavigate();
  const { notes, getNotes, editNote, getFilteredNotes, printNote } = context;
  
  useEffect(() => {
    if(localStorage.getItem('token')){
      getNotes();
    }
    else{
      navigate("/login")
    }
    // eslint-disable-next-line
  }, []);
  
  const ref = useRef(null);
  const refClose = useRef(null);
  const [note, setNote] = useState({
    id: "",
    etitle: "",
    edescription: "",
    etag: "",
    eattachments: [],
    eimages: [],
    etodoItems: []
  });
  
  const updateNote = (currentNote) => {
    ref.current.click();
    setNote({
      id: currentNote._id,
      etitle: currentNote.title,
      edescription: currentNote.description,
      etag: currentNote.tag || "",
      eattachments: currentNote.attachments || [],
      eimages: currentNote.images || [],
      etodoItems: currentNote.todoItems || []
    });
  };

  const handleClick = () => {
    editNote(
      note.id, 
      note.etitle, 
      note.edescription, 
      note.etag,
      note.eattachments,
      note.eimages,
      note.etodoItems
    );
    refClose.current.click();
    props.showAlert("Updated Successfully", "success");
  };
  
  const onChange = (e) => {
    setNote({ ...note, [e.target.name]: e.target.value });
  };

  const handleTodoChange = (index, field, value) => {
    const updatedTodos = [...note.etodoItems];
    updatedTodos[index] = { ...updatedTodos[index], [field]: value };
    setNote({ ...note, etodoItems: updatedTodos });
  };

  const addTodoItem = () => {
    setNote({
      ...note,
      etodoItems: [...note.etodoItems, { text: "", completed: false }]
    });
  };

  const removeTodoItem = (index) => {
    const updatedTodos = note.etodoItems.filter((_, i) => i !== index);
    setNote({ ...note, etodoItems: updatedTodos });
  };

  const handleImageUpload = (e) => {
    const files = Array.from(e.target.files);
    // In a real app, you'd upload to a server and get URLs
    // For now, we'll use FileReader to create data URLs
    files.forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setNote(prev => ({
          ...prev,
          eimages: [...prev.eimages, {
            name: file.name,
            url: event.target.result,
            size: file.size
          }]
        }));
      };
      reader.readAsDataURL(file);
    });
  };

  const removeImage = (index) => {
    const updatedImages = note.eimages.filter((_, i) => i !== index);
    setNote({ ...note, eimages: updatedImages });
  };

  const handleFileUpload = (e) => {
    const files = Array.from(e.target.files);
    files.forEach(file => {
      setNote(prev => ({
        ...prev,
        eattachments: [...prev.eattachments, {
          name: file.name,
          size: file.size,
          type: file.type
        }]
      }));
    });
  };

  const removeAttachment = (index) => {
    const updatedAttachments = note.eattachments.filter((_, i) => i !== index);
    setNote({ ...note, eattachments: updatedAttachments });
  };

  const filteredNotes = getFilteredNotes();

  // Print all notes
  const printAllNotes = () => {
    const printWindow = window.open('', '_blank');
    const notesHtml = filteredNotes.map(note => {
      let todoHtml = '';
      if (note.todoItems && note.todoItems.length > 0) {
        todoHtml = `
          <h4>Todo Items:</h4>
          <ul style="list-style: none; padding-left: 0;">
            ${note.todoItems.map(item => 
              `<li><input type="checkbox" ${item.completed ? 'checked' : ''} disabled> ${item.text}</li>`
            ).join('')}
          </ul>
        `;
      }
      
      return `
        <div style="margin-bottom: 30px; border-bottom: 1px solid #ccc; padding-bottom: 20px;">
          <h2>${note.title}</h2>
          <div>${note.description}</div>
          ${note.tag ? `<p><strong>Tags:</strong> ${note.tag}</p>` : ''}
          ${todoHtml}
          <div style="color: #888; font-size: 12px; margin-top: 10px;">
            Created: ${new Date(note.createdAt || note.date).toLocaleString()}
          </div>
        </div>
      `;
    }).join('');

    printWindow.document.write(`
      <html>
        <head>
          <title>All Notes - iNotebook</title>
          <style>
            body { font-family: Arial, sans-serif; margin: 20px; }
            h1 { color: #333; border-bottom: 2px solid #333; }
            h2 { color: #555; }
            h4 { color: #666; }
          </style>
        </head>
        <body>
          <h1>All Notes - iNotebook</h1>
          ${notesHtml}
        </body>
      </html>
    `);
    printWindow.document.close();
    printWindow.print();
  };
  
  return (
    <>
      <div className="d-flex justify-content-between align-items-center mb-3">
        <UndoRedoButtons />
        <div>
          <button 
            className="btn btn-outline-primary btn-sm me-2"
            onClick={printAllNotes}
            disabled={filteredNotes.length === 0}
          >
            <i className="fas fa-print me-1"></i>
            Print All Notes
          </button>
        </div>
      </div>

      <AddNote showAlert={props.showAlert} />
      
      <SearchAndFilter />
      
      <NoteStats />

      {/* Edit Note Modal */}
      <button
        type="button"
        ref={ref}
        className="btn btn-primary d-none"
        data-bs-toggle="modal"
        data-bs-target="#editNoteModal"
      >
        Launch demo modal
      </button>
      
      <div
        className="modal fade"
        id="editNoteModal"
        tabIndex="-1"
        aria-labelledby="editNoteModalLabel"
        aria-hidden="true"
      >
        <div className="modal-dialog modal-lg">
          <div className="modal-content">
            <div className="modal-header">
              <h5 className="modal-title" id="editNoteModalLabel">
                Edit Note
              </h5>
              <button
                type="button"
                className="btn-close"
                data-bs-dismiss="modal"
                aria-label="Close"
              ></button>
            </div>
            <div className="modal-body">
              <form>
                <div className="mb-3">
                  <label htmlFor="etitle" className="form-label">
                    Title
                  </label>
                  <input
                    type="text"
                    className="form-control"
                    id="etitle"
                    name="etitle"
                    value={note.etitle}
                    onChange={onChange}
                    minLength={5}
                    required
                  />
                </div>
                
                <div className="mb-3">
                  <label htmlFor="edescription" className="form-label">
                    Description
                  </label>
                  <textarea
                    className="form-control"
                    id="edescription"
                    name="edescription"
                    value={note.edescription}
                    onChange={onChange}
                    rows="4"
                    minLength={5}
                    required
                  />
                </div>
                
                <div className="mb-3">
                  <label htmlFor="etag" className="form-label">
                    Tags (comma separated)
                  </label>
                  <input
                    type="text"
                    className="form-control"
                    id="etag"
                    name="etag"
                    value={note.etag}
                    onChange={onChange}
                    placeholder="work, personal, important"
                  />
                </div>

                {/* Todo Items Section - Edit */}
                <div className="mb-3">
                  <label className="form-label">Todo Items</label>
                  {note.etodoItems.map((todo, index) => (
                    <div key={index} className="d-flex mb-2">
                      <div className="form-check me-2">
                        <input
                          className="form-check-input"
                          type="checkbox"
                          checked={todo.completed}
                          onChange={(e) => handleTodoChange(index, 'completed', e.target.checked)}
                        />
                      </div>
                      <input
                        type="text"
                        className="form-control me-2"
                        value={todo.text}
                        onChange={(e) => handleTodoChange(index, 'text', e.target.value)}
                        placeholder="Todo item"
                      />
                      <button
                        type="button"
                        className="btn btn-outline-danger btn-sm"
                        onClick={() => removeTodoItem(index)}
                      >
                        <i className="fas fa-trash"></i>
                      </button>
                    </div>
                  ))}
                  <button
                    type="button"
                    className="btn btn-outline-primary btn-sm"
                    onClick={addTodoItem}
                  >
                    <i className="fas fa-plus me-1"></i>Add Todo Item
                  </button>
                </div>

                {/* Image Upload Section - Edit */}
                <div className="mb-3">
                  <label htmlFor="eimageUpload" className="form-label">
                    Images
                  </label>
                  <input
                    type="file"
                    className="form-control"
                    id="eimageUpload"
                    multiple
                    accept="image/*"
                    onChange={handleImageUpload}
                  />
                  <div className="mt-2">
                    {note.eimages.map((image, index) => (
                      <div key={index} className="d-flex align-items-center mb-1">
                        <img 
                          src={image.url} 
                          alt={image.name} 
                          style={{ width: '50px', height: '50px', objectFit: 'cover' }} 
                          className="me-2"
                        />
                        <span className="me-2">{image.name}</span>
                        <button
                          type="button"
                          className="btn btn-outline-danger btn-sm"
                          onClick={() => removeImage(index)}
                        >
                          Remove
                        </button>
                      </div>
                    ))}
                  </div>
                </div>

                {/* File Attachments Section - Edit */}
                <div className="mb-3">
                  <label htmlFor="efileUpload" className="form-label">
                    File Attachments
                  </label>
                  <input
                    type="file"
                    className="form-control"
                    id="efileUpload"
                    multiple
                    onChange={handleFileUpload}
                  />
                  <div className="mt-2">
                    {note.eattachments.map((file, index) => (
                      <div key={index} className="d-flex align-items-center mb-1">
                        <i className="fas fa-file me-2"></i>
                        <span className="me-2">{file.name} ({Math.round(file.size / 1024)} KB)</span>
                        <button
                          type="button"
                          className="btn btn-outline-danger btn-sm"
                          onClick={() => removeAttachment(index)}
                        >
                          Remove
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              </form>
            </div>
            <div className="modal-footer">
              <button
                type="button"
                className="btn btn-secondary"
                data-bs-dismiss="modal"
                ref={refClose}
              >
                Close
              </button>
              <button
                disabled={
                  note.etitle.length < 5 || note.edescription.length < 5
                }
                type="button"
                className="btn btn-primary"
                onClick={handleClick}
              >
                Update Note
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Notes Display */}
      <div className="row my-3">
        <div className="d-flex justify-content-between align-items-center mb-3">
          <h1>Your Notes</h1>
          <small className="text-muted">
            Showing {filteredNotes.length} of {notes.length} notes
          </small>
        </div>
        
        <div className="container mx-1">
          {filteredNotes.length === 0 && notes.length === 0 && "No notes to display"}
          {filteredNotes.length === 0 && notes.length > 0 && "No notes match your search criteria"}
        </div>
        
        {filteredNotes.map((note) => {
          return (
            <Noteitem
              key={note._id}
              updateNote={updateNote}
              note={note}
              showAlert={props.showAlert}
            />
          );
        })}
      </div>
    </>
  );
};

export default Notes;
